func (b *BatchManager) validateBatchDelete(ctx context.Context, principal *models.Principal,
	match *models.BatchDeleteMatch, dryRun *bool, output *string,
) (*BatchDeleteParams, uint64, error) {
	if match == nil {
		return nil, 0, errors.New("empty match clause")  // line 128: plain errors.New, NOT ErrInvalidUserInput
	}

	if len(match.Class) == 0 {
		return nil, 0, errors.New("empty match.class clause")  // line 132: plain errors.New
	}

	if match.Where == nil {
		return nil, 0, errors.New("empty match.where clause")  // line 136: plain errors.New - THIS IS THE BUG
	}
	...
}

// usecases/objects/batch_delete.go line 78 (deleteObjects function)
params, schemaVersion, err := b.validateBatchDelete(ctx, principal, match, dryRun, output)
if err != nil {
	return nil, errors.Wrap(err, "validate")  // WRAPS plain error, still not ErrInvalidUserInput
}

// adapters/handlers/rest/handlers_batch_objects.go lines 185-197 (deleteObjects handler)
res, err := h.manager.DeleteObjects(ctx, principal,
	params.Body.Match, params.Body.DeletionTimeUnixMilli, params.Body.DryRun, params.Body.Output, repl, tenant)
if err != nil {
	h.metricRequestsTotal.logError("", err)
	if errors.As(err, &objects.ErrInvalidUserInput{}) {  // THIS CHECK FAILS because validateBatchDelete returns plain errors.New
		return batch.NewBatchObjectsDeleteUnprocessableEntity().  // NEVER EXECUTED
			WithPayload(errPayloadFromSingleErr(principal, err))
	} else {
		return batch.NewBatchObjectsDeleteInternalServerError().  // EXECUTED INSTEAD: 500 status
			WithPayload(errPayloadFromSingleErr(principal, err))
	}
}

